insert into _entities select 'group', o.slug, o.id from orbit.organizations o where o.slug = 'kestrion';
insert into _entities select 'region', r.slug, r.id from orbit.regions r join orbit.organizations o on o.id = r.organization_id where o.slug = 'kestrion';
insert into _entities select 'facility', f.slug, f.id from orbit.facilities f join orbit.organizations o on o.id = f.organization_id where o.slug = 'kestrion';
insert into _entities select 'coe', c.slug, c.id from orbit.coes c join orbit.organizations o on o.id = c.organization_id where o.slug = 'kestrion';
